using IndaloAventurApi.Domain.Inventario; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace IndaloAventurApi.Infrastructure.Persistence.Inventario;
public sealed class InventarioMaterialConfiguration:IEntityTypeConfiguration<InventarioMaterial>{public void Configure(EntityTypeBuilder<InventarioMaterial>b){b.ToTable("InventarioMateriales");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedOnAdd();b.Property(x=>x.Descripcion).HasMaxLength(250).IsRequired();b.Property(x=>x.MarcaModelo).HasMaxLength(200);b.Property(x=>x.AdquiridoDonado).HasMaxLength(250).IsRequired();b.Property(x=>x.Observaciones).HasMaxLength(2000);b.Property(x=>x.NumeroSerie).HasMaxLength(120);b.Property(x=>x.NumeroSerieNormalizado).HasMaxLength(120);b.Property(x=>x.Activo).HasDefaultValue(true).IsRequired();b.Property(x=>x.FechaAdquisicion).HasColumnType("date");b.HasOne<InventarioCategoria>().WithMany().HasForeignKey(x=>x.CategoriaId).OnDelete(DeleteBehavior.Restrict);b.HasOne<InventarioEstado>().WithMany().HasForeignKey(x=>x.EstadoId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.CategoriaId);b.HasIndex(x=>x.EstadoId);b.HasIndex(x=>x.NumeroSerieNormalizado).IsUnique().HasFilter("[NumeroSerieNormalizado] IS NOT NULL");}}
